class Solution {
    public int maxOperations(int[] nums,int k){
        Map<Integer,Integer> available=new HashMap<>();
        int answer=0;
        for(int value:nums){
            int complement=k-value;
            if(available.getOrDefault(complement,0)>0){
                available.put(complement,available.get(complement)-1);
                answer++;
            }else available.put(value,available.getOrDefault(value,0)+1);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxOperations(nums:IntArray,k:Int):Int{
        val available=mutableMapOf<Int,Int>();
        var answer=0;
        for(value in nums){
            val complement=k-value;
            if((available[complement]?:0)>0){
                available[complement]=available[complement]!!-1;
                answer++
            }else available[value]=(available[value]?:0)+1
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int maxOperations(vector<int>& nums,int k){
        unordered_map<int,int> available;
        int answer=0;
        for(int value:nums){
            int complement=k-value;
            if(available[complement]){
                --available[complement];
                ++answer;
            }else ++available[value];
        }
        return answer;
    }
};
